}

class Trie {
  constructor() { this.root = { kids: {}, end: false }; }
  insert(word) {
    let n = this.root;
    for (const c of word) { n.kids[c] ??= { kids: {}, end: false }; n = n.kids[c]; }
    n.end = true;
  }
  search(word) { let n = this.root; for (const c of word) { n = n.kids[c]; if (!n) return false; } return n.end; }
  startsWith(p) { let n = this.root; for (const c of p) { n = n.kids[c]; if (!n) return false; } return true; }
}

function findWords(board, words) {
  const root = { kids: {}, word: null };
  for (const w of words) {
    let n = root;
    for (const c of w) n.kids[c] ??= { kids: {}, word: null }, n = n.kids[c];
    n.word = w;
  }
  const out = [];
  const dfs = (r, c, node) => {
    const ch = board[r][c];
    const next = node.kids[ch];
    if (!next) return;
    if (next.word) { out.push(next.word); next.word = null; }
    board[r][c] = "#";
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nc >= 0 && nr < board.length && nc < board[0].length && board[nr][nc] !== "#") dfs(nr, nc, next);
    }
    board[r][c] = ch;
  };
  for (let r = 0; r < board.length; r++) for (let c = 0; c < board[0].length; c++) dfs(r, c, root);
  return out;
}

function singleNumber(nums) {
  return nums.reduce((acc, n) => acc ^ n, 0);
}

function countBits(n) {
  const dp = Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) dp[i] = dp[i >> 1] + (i & 1);
  return dp;
}

function merge(intervals) {
  intervals.sort((a, b) => a[0] - b[0]);
  const out = [];
  for (const iv of intervals) {
    const last = out[out.length - 1];
    if (last && iv[0] <= last[1]) last[1] = Math.max(last[1], iv[1]);
    else out.push([...iv]);
  }
  return out;
}

function insert(intervals, ni) {
  const out = [];
  let i = 0;
  while (i < intervals.length && intervals[i][1] < ni[0]) out.push(intervals[i++]);
  while (i < intervals.length && intervals[i][0] <= ni[1]) {
    ni = [Math.min(ni[0], intervals[i][0]), Math.max(ni[1], intervals[i][1])];
    i++;
  }
  out.push(ni);
  while (i < intervals.length) out.push(intervals[i++]);
  return out;
}

function eraseOverlapIntervals(intervals) {
  intervals.sort((a, b) => a[1] - b[1]);
  let keep = 0, end = -Infinity;
  for (const [s, e] of intervals) {
    if (s >= end) { keep++; end = e; }
  }
  return intervals.length - keep;
}
